package server

import (
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// compactChangesRequest is the body of POST .../changes/compact: the same
// device field the CRDT compaction endpoint carries.
type compactChangesRequest struct {
	DeviceID string `json:"deviceId"`
}

// compactChangesResponse is the success body of POST .../changes/compact. The
// struct field order fixes the key order (boundary, then removed), and the
// shared JSON writer emits it as one compact line with a trailing newline.
type compactChangesResponse struct {
	Boundary int64 `json:"boundary"`
	Removed  int64 `json:"removed"`
}

// handleCompactChanges moves the document's changes at or below the
// compaction boundary — the greatest cursor with a saved snapshot, zero when
// the document has none — out of the online change log.
//
// The request contract matches the CRDT compaction endpoint: strict
// application/json, exactly one JSON value, no trailing content and a
// non-empty deviceId — any violation is a 400 JSON error with zero writes.
// The gate then applies in the submission's order: an unregistered device is
// a 404 and a device whose permission for the document was revoked is a 403;
// neither writes anything. A snapshot-less or unknown document compacts
// successfully with boundary 0 and nothing removed.
//
// On success the answer is 200 with one compact JSON line naming the boundary
// and the number of changes this call removed. Compaction is idempotent — a
// repeat reports the same boundary and zero removed — and is not itself a
// change: it allocates no cursor, writes no change record and wakes no waiter
// or subscriber.
func handleCompactChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req compactChangesRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}

	boundary, removed, err := s.CompactChanges(documentID, req.DeviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact changes")
		}
		return
	}

	writeJSON(w, http.StatusOK, compactChangesResponse{Boundary: boundary, Removed: removed})
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// changeLookupRequest is the body of POST .../changes/query: the calling
// device and the non-empty, in-batch-unique set of change ids to answer. The
// device identity uses the same declaration the document-level change commit
// uses — no new authentication is introduced.
type changeLookupRequest struct {
	DeviceID string   `json:"deviceId"`
	IDs      []string `json:"ids"`
}

// changeLookupItem fixes the on-the-wire key order of one answer to id,
// status, then (for a found row) deviceId, payload and cursor. The
// device/payload/cursor fields are omitted entirely on missing and compacted
// answers: a compacted id reports only its first cursor, so it carries
// cursor alone alongside id and status, and a missing id carries nothing but
// its id and status.
type changeLookupItem struct {
	ID       string          `json:"id"`
	Status   string          `json:"status"`
	DeviceID string          `json:"deviceId,omitempty"`
	Payload  json.RawMessage `json:"payload,omitempty"`
	Cursor   int64           `json:"cursor,omitempty"`
}

// changeLookupResponse is the query body with the top-level key order fixed
// to results then count; count always equals the number of result entries,
// which equals the number of ids asked for.
type changeLookupResponse struct {
	Results []changeLookupItem `json:"results"`
	Count   int                `json:"count"`
}

// handleQueryChanges is the read-only batch lookup over a document's change
// collection:
//
//	POST /v1/documents/{documentID}/changes/query
//
// The strict application/json body names the calling device and a non-empty
// array of non-empty, in-batch-unique change ids; answers arrive in the exact
// order the ids were given. Each id is answered independently:
//
//   - "found": the change is still in the online log, so the answer carries
//     its originating device, the payload verbatim as it was saved at commit
//     time and its first cursor;
//   - "compacted": compaction trimmed the row, so the answer reports only the
//     first cursor held in its retained summary — no payload is restored and
//     the summary never participates in an ordinary read;
//   - "missing": the id has never belonged to the document, so the answer
//     carries no content. A missing id is a normal answer, not an error.
//
// The verdict order is request shape (400) first — content type, JSON
// validity, trailing content, a missing or empty ids array, an empty or
// mistyped element and an in-batch duplicate — then device existence (404)
// and document permission (403). A 404 or 403 exposes no change content. The
// query creates no change, allocates no cursor and wakes neither a long poll
// nor a push subscriber. Success is one compact JSON line ending in a
// newline with results then count.
func handleQueryChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req changeLookupRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	// Shape checks all precede the device existence verdict, so a malformed
	// query against an unregistered device is still a 400.
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	// A missing (nil) or empty ids array is the same request-shape error; a
	// non-string element was already rejected while decoding the JSON.
	if len(req.IDs) == 0 {
		writeError(w, http.StatusBadRequest, "ids must be a non-empty array of non-empty strings")
		return
	}
	seen := make(map[string]struct{}, len(req.IDs))
	for _, id := range req.IDs {
		if id == "" {
			writeError(w, http.StatusBadRequest, "each id must be a non-empty string")
			return
		}
		if _, dup := seen[id]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+id)
			return
		}
		seen[id] = struct{}{}
	}

	lookups, err := s.GetChangesByIDs(documentID, req.DeviceID, req.IDs)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to look up changes")
		}
		return
	}

	items := make([]changeLookupItem, len(lookups))
	for i, l := range lookups {
		items[i] = changeLookupItem{
			ID:       l.ID,
			Status:   l.Status,
			DeviceID: l.DeviceID,
			Payload:  l.Payload,
			Cursor:   l.Cursor,
		}
	}
	writeJSON(w, http.StatusOK, changeLookupResponse{Results: items, Count: len(items)})
}

// malformedChangeQueryPath reports whether p targets the change-log batch
// lookup but is not at its exact location
// (/v1/documents/{documentID}/changes/query): a missing "changes" segment, an
// extra segment, a trailing slash (an empty trailing segment), or a "query"
// segment in a position short of the registered shape. ServeMux would answer
// those with a redirect or a plain-text 404/405; every failure of this
// endpoint must be a JSON 400 instead and never a redirect. Empty segments
// are already rejected by the guard itself.
//
// "query" is treated as the endpoint keyword only in its terminal segment
// position (the third segment, index 2); a document identifier literally
// named "query" occupies an identifier position (index 0) and keeps its
// ordinary routes.
func malformedChangeQueryPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guards; "query" there is an ordinary identifier.
	if len(segs) >= 2 && segs[1] == "crdt" {
		return false
	}
	// The named-snapshot-version subtree owns its own shape verdict.
	if len(segs) >= 3 && segs[0] != "" && segs[1] == "snapshots" && segs[2] == "versions" {
		return false
	}
	for i, seg := range segs {
		if seg != "query" {
			continue
		}
		// Identifier position: a document named "query" is an ordinary id.
		if i == 0 {
			continue
		}
		// Endpoint keyword position: the third segment must be exactly
		// "query" with a non-empty documentID and "changes" around it, and no
		// segment may follow. Any other occurrence is a malformed path.
		if i == 2 && len(segs) == 3 &&
			segs[0] != "" &&
			segs[1] == "changes" {
			return false
		}
		return true
	}
	return false
}

package server

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"mime"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// maxBatchBytes caps an inbound POST body.
const maxBatchBytes = 10 << 20

// defaultListLimit is used when GET omits limit.
const defaultListLimit = 100

// maxListLimit is the largest page size GET accepts.
const maxListLimit = 1000

// maxPollWaitMillis is the longest waitMs a long poll accepts.
const maxPollWaitMillis = 30000

type changeIn struct {
	ID      string          `json:"id"`
	Payload json.RawMessage `json:"payload"`
}

type postRequest struct {
	DeviceID string     `json:"deviceId"`
	Changes  []changeIn `json:"changes"`
}

type mergeChangeIn struct {
	ID      string          `json:"id"`
	Payload json.RawMessage `json:"payload"`
}

type mergeRequest struct {
	DeviceID   string          `json:"deviceId"`
	BaseCursor json.RawMessage `json:"baseCursor"`
	Change     *mergeChangeIn  `json:"change"`
}

type snapshotPostRequest struct {
	Cursor json.RawMessage `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

type restoreRequest struct {
	DeviceID       string          `json:"deviceId"`
	ChangeID       string          `json:"changeId"`
	SnapshotCursor json.RawMessage `json:"snapshotCursor"`
}

type deviceRequest struct {
	DeviceID string `json:"deviceId"`
}

type permissionRequest struct {
	DeviceID string `json:"deviceId"`
	Action   string `json:"action"`
}

type sessionRequest struct {
	SessionID string `json:"sessionId"`
}

type sessionPostRequest struct {
	Changes []changeIn `json:"changes"`
}

// sessionReplayRequest is the session-scoped replay body: only the ordered
// operations array travels in the request. The calling device is the session's
// owning device resolved from the path, so a stray deviceId is decoded and
// ignored like every other unknown field.
type sessionReplayRequest struct {
	Operations []changeIn `json:"operations"`
}

type replayRequest struct {
	DeviceID   string     `json:"deviceId"`
	Operations []changeIn `json:"operations"`
}

// NewHandlerWithReadiness builds the same public HTTP surface as NewHandler but
// answers every request — including GET /healthz — with a 503 JSON error until
// ready reports that the database is open and the listener is accepting
// connections. Once ready, responses are byte-for-byte what NewHandler emits;
// readiness is one-way, so a later flip back is not part of the contract.
func NewHandlerWithReadiness(s *app.App, ready func() bool) http.Handler {
	h := NewHandler(s)
	if ready == nil {
		return h
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !ready() {
			writeError(w, http.StatusServiceUnavailable, "service is not ready")
			return
		}
		h.ServeHTTP(w, r)
	})
}

// NewHandler builds the public HTTP surface backed by s.
func NewHandler(s *app.App) http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})

	mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
		handleRegisterDevice(s, w, r)
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}", func(w http.ResponseWriter, r *http.Request) {
		handleDeregisterDevice(s, w, r)
	})
	// The device item path accepts only DELETE (deregistration); every other
	// verb gets a JSON 400 rather than the subtree's unknown-path JSON 404.
	mux.HandleFunc("/v1/devices/{deviceId}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	// A DELETE short of the device id misses the segment that names the
	// deregistering device; answer a JSON 400 instead of the collection's
	// unknown-path JSON 404.
	mux.HandleFunc("DELETE /v1/devices", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "device deregistration path is malformed")
	})
	// Non-POST verbs on the exact collection path: the method-less pattern is
	// less specific than POST above, so it only catches the rest and answers a
	// JSON 404 instead of ServeMux's slash redirect. The explicit DELETE
	// pattern above wins for a bodyless deregistration missing its id segment.
	mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusNotFound, "unknown device path")
	})
	mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusNotFound, "unknown session path")
	})
	mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
		handleCreateSession(s, w, r)
	})
	// The read-only session listing shares the collection path with session
	// creation: GET pages the device's live sessions by id, limit/offset, the
	// way the attachment listing pages uploads. The path device id is the
	// caller's only identity and the request carries no body.
	mux.HandleFunc("GET /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
		handleListSessions(s, w, r)
	})
	// The session collection path accepts GET (list) and POST (create); every
	// other verb on its exact shape gets a JSON 400 rather than ServeMux's
	// plain-text 405. The more specific GET/POST patterns above win.
	mux.HandleFunc("/v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	// A GET carrying a segment past the collection is a malformed list read
	// and answers a JSON 400 instead of the subtree's unknown-path 404; the
	// exact DELETE item pattern above still wins for its own shape. A device
	// id literally named "sessions" stays an ordinary id — "sessions" is the
	// endpoint word only in this collection segment.
	mux.HandleFunc("GET /v1/devices/{deviceId}/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "session list path is malformed")
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
		handleDeleteSession(s, w, r)
	})
	// The read-only document listing shares the device subtree with the
	// session and attachment collections: GET pages the distinct documents
	// this device's sessions once wrote changes to, by document id and
	// limit/offset, the way the session listing pages sessions. The path
	// device id is the caller's only identity and the request carries no body.
	mux.HandleFunc("GET /v1/devices/{deviceId}/documents", func(w http.ResponseWriter, r *http.Request) {
		handleListDocuments(s, w, r)
	})
	// The document collection path accepts only GET; every other verb on its
	// exact shape gets a JSON 400 rather than ServeMux's plain-text 405. The
	// more specific GET pattern above wins.
	mux.HandleFunc("/v1/devices/{deviceId}/documents", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	// Any path carrying a segment past the collection is a malformed list
	// read and answers a JSON 400 instead of the subtree's unknown-path 404,
	// for every verb (the collection has no item subresource, so every deeper
	// shape is malformed). A device id literally named "documents" stays an
	// ordinary id — "documents" is the endpoint word only in this collection
	// segment.
	mux.HandleFunc("/v1/devices/{deviceId}/documents/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "document list path is malformed")
	})
	// The read-only pending-change statistics hang one pending segment below
	// the document collection: GET pages the per-document online change counts
	// of the device, by document id and limit/offset, on the listing's exact
	// order and scope. The path device id is the caller's only identity and the
	// request carries no body.
	mux.HandleFunc("GET /v1/devices/{deviceId}/documents/pending", func(w http.ResponseWriter, r *http.Request) {
		handleListPendingChanges(s, w, r)
	})
	// The pending path accepts only GET; every other verb on its exact shape
	// gets a JSON 400 rather than ServeMux's plain-text 405. The more specific
	// GET pattern above wins.
	mux.HandleFunc("/v1/devices/{deviceId}/documents/pending", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	// Extra segments past pending are a malformed statistics read and answer a
	// JSON 400 instead of the subtree's unknown-path 404, for every verb. A
	// device id literally named "pending" stays an ordinary id — "pending" is
	// the endpoint word only in this terminal segment.
	mux.HandleFunc("/v1/devices/{deviceId}/documents/pending/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "document pending path is malformed")
	})
	// Device-scoped subscription management: a read-only list of the device's
	// live push connections and a DELETE that actively cancels one of them.
	// The path device id is the only identity, exactly like the session
	// routes above it.
	mux.HandleFunc("GET /v1/devices/{deviceId}/subscriptions", func(w http.ResponseWriter, r *http.Request) {
		handleListDeviceSubscriptions(s, w, r)
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}/subscriptions/{subscriptionId}", func(w http.ResponseWriter, r *http.Request) {
		handleCancelDeviceSubscription(s, w, r)
	})
	// The collection path accepts only GET and the item path only DELETE;
	// every other verb on either exact shape gets a JSON 400 rather than
	// ServeMux's plain-text 405.
	mux.HandleFunc("/v1/devices/{deviceId}/subscriptions", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	mux.HandleFunc("/v1/devices/{deviceId}/subscriptions/{subscriptionId}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	// Extra segments past either management path are a malformed path and
	// answer a JSON 400 instead of the subtree's unknown-path 404; the exact
	// item pattern above still wins for its exact shape. Empty segments and a
	// trailing slash are already a 400 via emptyIDGuard.
	mux.HandleFunc("/v1/devices/{deviceId}/subscriptions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "subscription path is malformed")
	})
	mux.HandleFunc("POST /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
		handleCreateAttachment(s, w, r)
	})
	mux.HandleFunc("GET /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
		handleListAttachments(s, w, r)
	})
	// The attachment collection path accepts GET (list), POST (create) and
	// DELETE (the malformed-delete 400 below); every other verb gets a JSON
	// 400 rather than ServeMux's plain-text 405.
	mux.HandleFunc("/v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	// A GET with extra segments past the collection or item path is a
	// malformed list/read and answers a JSON 400 instead of the subtree 404;
	// the more specific chunks route above still wins for its exact shape.
	mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "attachment list path is malformed")
	})
	mux.HandleFunc("PUT /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
		handlePutChunk(s, w, r)
	})
	mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/complete", func(w http.ResponseWriter, r *http.Request) {
		handleCompleteAttachment(s, w, r)
	})
	mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/access", func(w http.ResponseWriter, r *http.Request) {
		handleSetAttachmentAccess(s, w, r)
	})
	mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/access", func(w http.ResponseWriter, r *http.Request) {
		handleListAttachmentAccess(s, w, r)
	})
	// The access subresource accepts GET (roster) and POST (grant/revoke);
	// every other verb gets a JSON 400, and extra segments past it are a
	// malformed path that also answers a JSON 400. A method-less pattern
	// cannot be used here — it would conflict with the GET extra-segment
	// wildcard above, which already answers GET .../access/{extra} — so the
	// rejected verbs (including POST with a stray segment) are named
	// explicitly.
	accessBad := func(message string) http.HandlerFunc {
		return func(w http.ResponseWriter, _ *http.Request) {
			writeError(w, http.StatusBadRequest, message)
		}
	}
	for _, method := range []string{http.MethodPost, http.MethodPut, http.MethodDelete, http.MethodPatch, http.MethodOptions} {
		mux.HandleFunc(method+" /v1/devices/{deviceId}/attachments/{attachmentId}/access/{rest...}",
			accessBad("attachment access path is malformed"))
	}
	for _, method := range []string{http.MethodPut, http.MethodDelete, http.MethodPatch, http.MethodOptions} {
		mux.HandleFunc(method+" /v1/devices/{deviceId}/attachments/{attachmentId}/access",
			accessBad("method is not allowed on this path"))
	}
	mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/content", func(w http.ResponseWriter, r *http.Request) {
		handleGetAttachmentContent(s, w, r)
	})
	// The content subresource accepts only GET: every other verb on the exact
	// path gets a JSON 400, and extra segments past it are a malformed path
	// that also answers a JSON 400. Like the access subresource, the rejected
	// verbs are named explicitly — a method-less pattern would conflict with
	// the GET extra-segment wildcard above, which already answers
	// GET .../content/{extra}.
	for _, method := range []string{http.MethodPost, http.MethodPut, http.MethodDelete, http.MethodPatch, http.MethodOptions} {
		mux.HandleFunc(method+" /v1/devices/{deviceId}/attachments/{attachmentId}/content",
			accessBad("method is not allowed on this path"))
		mux.HandleFunc(method+" /v1/devices/{deviceId}/attachments/{attachmentId}/content/{rest...}",
			accessBad("attachment content path is malformed"))
	}
	mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
		handleGetAttachment(s, w, r)
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
		handleDeleteAttachment(s, w, r)
	})
	// The attachment item path accepts only GET and DELETE; every other verb
	// gets a JSON 400 rather than ServeMux's plain-text 405. A DELETE short of
	// the attachment id or with extra segments is a malformed delete and also
	// answers a JSON 400 instead of the subtree 404.
	mux.HandleFunc("/v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "method is not allowed on this path")
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "attachment delete path is malformed")
	})
	mux.HandleFunc("DELETE /v1/devices/{deviceId}/attachments/{attachmentId}/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
		writeError(w, http.StatusBadRequest, "attachment delete path is malformed")
	})
	mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
		handleGetChunk(s, w, r)
	})
	mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
		handleSessionChanges(s, w, r)
	})
	mux.HandleFunc("POST /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
		handleSessionPostChanges(s, w, r)
	})
	// Verbs other than GET/POST on the session change collection path: the
	// exact GET and POST patterns above are more specific, so only other
	// verbs reach this method-less pattern and get a JSON 400 instead of the
	// subtree's unknown-path JSON 404. The paged read and the interval export
